; CYCLES_FORWARD_BRANCHES
; AERIA WIND -- generated by wind/gen.py, do not edit.
; The Balloon Shop's wind (MoreWeather.h, Wind): the sound is read through one delay that keeps
; drifting -- a few cents sharp, then flat, up to DPTH in a strong gust -- swells a little with
; each gust (x 0.93 .. 1.18) and leans to one side with it. Both channels read the same delay.
;
;  knob 0 AMT   the weather's fade 0..127 = 0..1: mix = smoothstep(1.5 amt), lean x amt
;  knob 1 DPTH  largest drift in a full gust, 0..2.4 % (64 = 1.2 % = 20.6 cents, the plugin)
;  knob 2 GUST  gusts: one every 3.5 s x 2^((64 - v)/16)   (64 = the plugin)
;  knob 3 LEAN  how far a gust leans the sound: x v/64 of the plugin's -35 % / +12 %
;
; AMT 0 and settled: REST, the routine returns at once (output = input, bit for bit). Coming up
; from rest the ring is cleared over 16 dry calls (256 words each), then it runs.
; The control tick (gusts, lean, a new delay target every 0.3 .. 1.4 s, the delay's velocity,
; the swell) runs once a call (16 frames, 0.363 ms) on a 24-bit LCG.
; Read: 4-point Hermite (Catmull-Rom), the plugin's, weights computed once a frame for both sides.
;
; Y ring: 4096 words at the base X:$213 points to; the base must be a multiple of 4096.
; L on even addresses, R on odd.
; r7: 00 ST 01 YB 02 WP 03 AMH 04 AML 05 RNG 06 ROLL 07 ENV 08 LEANT 09 LEANN 0a HOLD 0b DTGT 0c DH 0d DL 0e VL 0f VX 10 G2 11 AL 12 BL 13 AR 14 BR 15 DAL 16 DBL 17 DAR 18 DBR 19 W0 1a W1 1b W2 1c W3 1d MAXV0 1e GTHR 1f GLAST 20 GG 21 WMIX 22 CHL 23 CHR 24 LNK

init:
        move    #>$ffffff,m4
        move    r7,r4
        clr     a
        do      #64,>wnzero
        move    a,x:(r4)+
wnzero:
        nop
        move    x:>$213,r4
        nop
        move    x:(r4),a
        move    a,x:(r7+$01)
        move    a,x:(r7+$02)
        move    #>$009057,a             ; the plugin's seed
        move    a,x:(r7+$05)
        move    #>$ffffff,a
        move    a,x:(r7+$1f)
        rts
proc:
        move    x:(r7+$00),a
        tst     a
        bne     wnawake
        move    x:(r6),a
        tst     a
        bne     wnwake
        rts                             ; REST: nothing touched
wnwake:
; ---- up from rest: the plugin's reset values, then 16 clearing calls
        clr     a
        move    a,x:(r7+$03)
        move    a,x:(r7+$04)
        move    a,x:(r7+$06)
        move    a,x:(r7+$07)
        move    a,x:(r7+$08)
        move    a,x:(r7+$09)
        move    a,x:(r7+$0a)
        move    a,x:(r7+$0d)
        move    a,x:(r7+$0e)
        move    a,x:(r7+$0f)
        move    a,x:(r7+$12)
        move    a,x:(r7+$14)
        move    #>$000214,a
        move    a,x:(r7+$0c)
        move    a,x:(r7+$0b)
        move    #>$400000,a
        move    a,x:(r7+$10)
        move    a,x:(r7+$11)
        move    a,x:(r7+$13)
        move    x:(r7+$01),a
        move    a,x:(r7+$02)
        move    x:(r6+$3),a             ; LEAN starts where the knob is (glided from here on)
        move    a,x:(r7+$24)
        move    #>$000010,a
        move    a,x:(r7+$00)
        rts
wnawake:
        blt     wnrun
; ---- clearing: call n (16 .. 1) clears words (n - 1) * 256 ..
        sub     #>$1,a
        move    a,x:(r7+$00)
        asl     #$8,a,a
        move    x:(r7+$01),x0
        add     x0,a
        move    a1,r4
        move    #>$ffffff,m4
        clr     b
        do      #>$000100,>wnclr
        move    b,y:(r4)+
wnclr:
        nop
        move    x:(r7+$00),a
        tst     a
        bne     wnkeep
        move    #>$ffffff,a             ; cleared: RUN from the next call
        move    a,x:(r7+$00)
wnkeep:
        rts
wnrun:
; ---- amount: knob / 127, glided (1/64 a call = 23 ms, 48 bits); at 0 and settled -> REST
        move    x:(r6),x0
        move    #>$408102,y0
        mpy     y0,x0,a
        asl     a
        move    x:(r7+$03),b
        move    x:(r7+$04),b0
        sub     b,a
        asr     #$6,a,a
        add     a,b
        move    b1,x:(r7+$03)
        move    b0,x:(r7+$04)
        move    x:(r6),a
        tst     a
        bne     wngo
        move    x:(r7+$03),a
        cmp     #>$000040,a
        bge     wngo
        clr     a
        move    a,x:(r7+$00)
        rts
wngo:
; mix = smoothstep(min(1, 1.5 amt))
        move    x:(r7+$03),a
        move    a,b
        asr     b
        add     b,a
        move    a,x0
        mpy     x0,x0,a
        move    a,x1                    ; x^2
        move    #>$600000,a
        move    #>$400000,y0
        mac     -y0,x0,a                ; 0.75 - x/2
        move    a,y0
        mpy     x1,y0,a
        asl     #$2,a,a                 ; x^2 (3 - 2x); the move that takes it limits at 1
        move    a,x:(r7+$21)
; ---- GUST knob (only when it moved): threshold = p x 2^((v - 64)/16)
        move    x:(r6+$2),a
        move    x:(r7+$1f),x0
        cmp     x0,a
        beq     wngsame
        move    a,x:(r7+$1f)
        move    #>$7f0000,b
        sub     a,b
        asr     #$2,b,b                 ; y/32, y = (127 - v)/16
        move    b1,a
        bsr     wnexp
        move    b,x0
        move    #>$00340b,y0
        mpy     y0,x0,a
        move    a,x:(r7+$1e)
wngsame:
; DPTH: full-gust velocity = 0.024 x v/128 samples a sample, in 2^-24 samples
        move    x:(r6+$1),x0
        move    #>$0624dd,y0
        mpy     y0,x0,a
        move    a,x:(r7+$1d)
; ======== the control tick ========
; a gust now and then: roll = max(roll, 0.4 + 0.6 u), a new side to lean to
        bsr     wnrand
        move    x:(r7+$1e),x1
        cmp     x1,a
        bge     wncalm
        bsr     wnrand
        move    #>$4ccccd,y0
        mpy     y0,x0,a
        add     #>$333333,a
        move    x:(r7+$06),x1
        cmp     x1,a
        tlt     x1,a
        move    a,x:(r7+$06)
        bsr     wnrand
        asl     a
        sub     #>$7fffff,a
        move    a,x:(r7+$08)
wncalm:
; roll dies away (2.2 s); env follows it up in 0.5 s and down at once
        move    x:(r7+$06),x0
        move    #>$7ffa99,y0
        mpy     y0,x0,a
        move    a,x:(r7+$06)
        move    x:(r7+$07),b
        sub     b,a
        bgt     wnswell
        move    x:(r7+$06),b
        bra     wnenvd
wnswell:
        move    a,x0
        move    #>$0017c5,y0
        mpy     y0,x0,a
        add     a,b
wnenvd:
        move    b,x:(r7+$07)
        add     #>$133333,b
        move    b,x0                    ; g = min(1, 0.15 + env)
        move    x0,x:(r7+$20)
; lean glides to target x g (0.6 s)
        move    x:(r7+$08),y1
        mpy     x0,y1,a
        move    x:(r7+$09),b
        sub     b,a
        asr     a
        move    a,x1
        move    #>$00279e,y0
        mpy     x1,y0,a
        add     a,b
        move    b,x:(r7+$09)
; a new delay to drift to, every 0.3 .. 1.4 s
        move    x:(r7+$0a),a
        sub     #>$1,a
        move    a,x:(r7+$0a)
        bgt     wnheld
        bsr     wnrand
        move    #>$000bd8,y0
        mpy     y0,x0,a
        add     #>$00033b,a
        move    a,x:(r7+$0a)
        bsr     wnrand
        move    #>$000422,y0
        mpy     y0,x0,a
        add     #>$0000b3,a
        move    a,x:(r7+$0b)
wnheld:
; velocity: towards (target - delay) / 0.5 s, held to the gust's limit, glided (0.12 s)
        move    x:(r7+$20),x0
        move    #>$600000,y0
        mpy     y0,x0,a
        add     #>$200000,a
        move    a,x0
        move    x:(r7+$1d),y0
        mpy     y0,x0,a
        move    a,x1                    ; the limit
        move    x:(r7+$0b),a
        move    x:(r7+$0c),x0
        sub     x0,a
        asl     #$a,a,a
        move    a,x0
        move    #>$5f1be3,y0
        mpy     y0,x0,a
        cmp     x1,a
        tgt     x1,a
        move    x1,b
        neg     b
        move    b,x1
        cmp     x1,a
        tlt     x1,a
        move    x:(r7+$0e),b
        sub     b,a
        move    a,x0
        move    #>$0062ec,y0
        mpy     y0,x0,a
        add     a,b
        move    b,x:(r7+$0e)
        move    #>$ffffff,x1
        clr     a
        tst     b
        tmi     x1,a
        move    a1,x:(r7+$0f)                 ; its sign, for the 48-bit add
; the swell: gain/2 glides to 0.5 + 0.125 (g - 0.3)
        move    x:(r7+$20),a
        asr     #$3,a,a
        add     #>$3b3333,a
        move    x:(r7+$10),b
        sub     b,a
        move    a,x0
        move    #>$011c17,y0
        mpy     y0,x0,a
        add     a,b
        move    b,x:(r7+$10)
; ======== this call's gains: out = 2 (A dry + B wet) a side ========
; lean l = amt x leanNow x LEAN/2; the side it leans to x (1 - 0.35 l), the other x (1 + 0.12 l)
        move    x:(r7+$03),x0
        move    x:(r7+$09),y1
        mpy     x0,y1,a
        move    a,x0
        move    x:(r6+$3),a             ; LEAN glided 1/16 a call (5.8 ms): a jumped knob must not step the gains
        move    x:(r7+$24),b
        sub     b,a
        asr     #$4,a,a
        add     a,b
        move    b,x:(r7+$24)
        move    b,y1
        mpy     x0,y1,a
        move    a,x0                    ; signed
        abs     a
        move    a,x1
        move    #>$2ccccd,y0
        mpy     x1,y0,a
        neg     a
        add     #>$400000,a
        move    #>$0f5c29,y0
        mpy     x1,y0,b
        add     #>$400000,b
        move    a,y0                    ; the side leaned to (halved)
        move    b,y1                    ; the other
        move    x0,a
        tst     a
        ble     wnleft
        move    y0,x:(r7+$22)                ; lean > 0: the plugin turns the LEFT down
        move    y1,x:(r7+$23)
        bra     wnsides
wnleft:
        move    y1,x:(r7+$22)
        move    y0,x:(r7+$23)
wnsides:
        move    x:(r7+$21),x0
        move    x:(r7+$10),y1
        mpy     x0,y1,a
        move    a,x1                    ; w x gain / 2
        move    #>$7fffff,a
        sub     x0,a
        move    a,x0                    ; 1 - w
        move    x:(r7+$22),y0
        mpy     y0,x0,a
        move    x:(r7+$11),b
        sub     b,a
        asr     #$4,a,a
        move    a,x:(r7+$15)
        mpy     x1,y0,a
        asl     a
        move    x:(r7+$12),b
        sub     b,a
        asr     #$4,a,a
        move    a,x:(r7+$16)
        move    x:(r7+$23),y0
        mpy     y0,x0,a
        move    x:(r7+$13),b
        sub     b,a
        asr     #$4,a,a
        move    a,x:(r7+$17)
        mpy     x1,y0,a
        asl     a
        move    x:(r7+$14),b
        sub     b,a
        asr     #$4,a,a
        move    a,x:(r7+$18)
; ======== the frames ========
        move    #>$000fff,m1
        move    #>$000fff,m3
        move    x:(r7+$02),r1
        move    #>$1,n0
        do      n7,>wnframes
; delay += velocity (48 bits: whole samples, fraction)
        move    x:(r7+$0c),a
        move    x:(r7+$0d),a0
        move    x:(r7+$0f),x1
        move    x:(r7+$0e),x0
        add     x,a
        move    a1,x:(r7+$0c)
        move    a0,x:(r7+$0d)
        move    a1,n1
        move    a1,n3
        move    a0,b
        not     b
        lsr     b
        move    b1,x0                   ; t = 1 - fraction
; Hermite weights: W0 = t2 - (t3 + t)/2, W2 = 2 t2 + (t - 3 t3)/2, W3 = (t3 - t2)/2, W1 = 1 - the rest
        mpy     x0,x0,a
        move    a,x1                    ; t2
        mpy     x1,x0,b
        move    b,y0                    ; t3
        sub     x1,b
        asr     b
        move    b,x:(r7+$1c)
        move    b,a
        move    y0,b
        add     x0,b
        asr     b
        neg     b
        add     x1,b
        move    b,x:(r7+$19)
        add     b,a
        move    y0,b
        asl     b
        add     y0,b
        neg     b
        add     x0,b
        asr     b
        add     x1,b
        add     x1,b
        move    b,x:(r7+$1b)
        add     b,a
        move    #>$7fffff,b
        sub     a,b
        move    b,x:(r7+$1a)
; write the frame, then read 4 frames from delay + 1 back
        move    x:(r0),a
        move    a,y:(r1)+
        move    x:(r0+n0),a
        move    a,y:(r1)+
        lua     (r1)-n1,r3
        lua     (r3)-n3,r3
        clr     a
        clr     b
        move    x:(r7+$19),y0
        move    y:(r3)+,x0
        mac     y0,x0,a
        move    y:(r3)+,x0
        mac     y0,x0,b
        move    x:(r7+$1a),y0
        move    y:(r3)+,x0
        mac     y0,x0,a
        move    y:(r3)+,x0
        mac     y0,x0,b
        move    x:(r7+$1b),y0
        move    y:(r3)+,x0
        mac     y0,x0,a
        move    y:(r3)+,x0
        mac     y0,x0,b
        move    x:(r7+$1c),y0
        move    y:(r3)+,x0
        mac     y0,x0,a
        move    y:(r3)+,x0
        mac     y0,x0,b
        move    a,x1                    ; wet L
        move    b,y1                    ; wet R
; left: 2 (A dry + B wet), A and B ramped to this call's values
        move    x:(r7+$11),b
        move    x:(r7+$15),y0
        add     y0,b
        move    b,x:(r7+$11)
        move    b,y0
        move    x:(r0),x0
        mpy     y0,x0,a
        move    x:(r7+$12),b
        move    x:(r7+$16),y0
        add     y0,b
        move    b,x:(r7+$12)
        move    b,y0
        mac     x1,y0,a
        asl     a
        move    a,x:(r0)+
; right
        move    x:(r7+$13),b
        move    x:(r7+$17),y0
        add     y0,b
        move    b,x:(r7+$13)
        move    b,y0
        move    x:(r0),x0
        mpy     y0,x0,a
        move    x:(r7+$14),b
        move    x:(r7+$18),x0
        add     x0,b
        move    b,x:(r7+$14)
        move    b,x0
        mac     x0,y1,a
        asl     a
        move    a,x:(r0)+
wnframes:
        nop
        move    r1,x:(r7+$02)
        move    #>$ffffff,m1
        move    #>$ffffff,m3
; the delay stays inside 2 .. 30 ms
        move    x:(r7+$0c),a
        move    #>$00005c,x0
        cmp     x0,a
        bge     wnlook
        move    x0,x:(r7+$0c)
        clr     b
        move    b,x:(r7+$0d)
wnlook:
        move    #>$00052e,x0
        cmp     x0,a
        blt     wndone
        move    x0,x:(r7+$0c)
        clr     b
        move    b,x:(r7+$0d)
wndone:
        rts
; ---- subroutines (after their callers) ----
wnrand:
        move    x:(r7+$05),x0
        move    #>$0343fd,y0
        mpy     y0,x0,a
        asr     a                       ; a1:a0 = the whole product, a0 its low 24 bits
        move    a0,x0
        move    x0,a
        add     #>$269ec3,a
        move    a1,x:(r7+$05)
        move    a1,b
        lsr     b
        move    b1,x0
        move    x0,a
        rts
wnexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>wnpow
        asr     b
wnpow:
        asl     b
        rts
